using UnityEngine;

namespace Tapzy.Core
{
    /// <summary>One catalogue entry per mini-game. Generated by Tapzy > Setup Project from [MiniGame].</summary>
    public class GameDefinition : ScriptableObject
    {
        public string id;
        public string title;
        public string kind;
        public string sceneName;
        public Color tileColour = Color.white;
        public Sprite icon;
        public int order;

        [Header("Score validation (the server owns these once the backend is live)")]
        public float maxScorePerSecond = 100f;
        public float scoreBase;
        public float minDuration = 1f;

        [Header("Missions")]
        public int missionScore = 100;
    }
}
